def run_tool(call):
    if not isinstance(call, dict) or call.get("name") != "add":
        raise ValueError("Unsupported tool")
    args = call.get("arguments")
    if not isinstance(args, dict) or set(args) != {"a", "b"}:
        raise ValueError("Expected a and b")
    if any(type(args[key]) is not int for key in ("a", "b")):
        raise ValueError("Expected integers")
    return args["a"] + args["b"]
